CREATE TABLE public.petty_cash_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),branch_id text NOT NULL REFERENCES public.branches(id),name text NOT NULL CHECK(length(trim(name))>0));
GRANT SELECT ON public.petty_cash_categories TO authenticated; GRANT ALL ON public.petty_cash_categories TO service_role;
ALTER TABLE public.petty_cash_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY petty_categories_read ON public.petty_cash_categories FOR SELECT TO authenticated USING(public.staff_can('Manage expenses',branch_id));
CREATE UNIQUE INDEX petty_category_unique ON public.petty_cash_categories(branch_id,lower(trim(name)));
ALTER TABLE public.petty_cash_entries ADD COLUMN category_id uuid REFERENCES public.petty_cash_categories(id);
INSERT INTO public.petty_cash_categories(branch_id,name) SELECT DISTINCT branch_id,category FROM public.petty_cash_entries WHERE kind='Expense';
UPDATE public.petty_cash_entries e SET category_id=c.id FROM public.petty_cash_categories c WHERE e.kind='Expense' AND e.branch_id=c.branch_id AND e.category=c.name;
CREATE FUNCTION public.manage_petty_cash_category(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=p->>'branch_id';cid uuid:=nullif(p->>'id','')::uuid;n text:=nullif(trim(p->>'name'),'');oldname text; BEGIN IF NOT public.staff_can('Manage expenses',b) THEN RAISE EXCEPTION 'Expense management permission required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('petty-category-'||b,0)); IF cid IS NOT NULL THEN SELECT name INTO oldname FROM public.petty_cash_categories WHERE id=cid AND branch_id=b FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Category not found in this branch'; END IF; END IF; IF p->>'action'='Remove' THEN IF cid IS NULL THEN RAISE EXCEPTION 'Choose a category'; END IF; IF EXISTS(SELECT 1 FROM public.petty_cash_entries WHERE category_id=cid OR (branch_id=b AND kind='Expense' AND category=oldname)) THEN RAISE EXCEPTION 'This category is used by expenses and cannot be removed'; END IF; DELETE FROM public.petty_cash_categories WHERE id=cid; ELSE IF n IS NULL THEN RAISE EXCEPTION 'Enter a category name'; END IF; IF EXISTS(SELECT 1 FROM public.petty_cash_categories WHERE branch_id=b AND lower(trim(name))=lower(n) AND id IS DISTINCT FROM cid) THEN RAISE EXCEPTION 'This category already exists'; END IF; IF cid IS NULL THEN INSERT INTO public.petty_cash_categories(branch_id,name) VALUES(b,n) RETURNING id INTO cid; ELSE UPDATE public.petty_cash_categories SET name=n WHERE id=cid; END IF; END IF; INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),b,'Expense categories',CASE WHEN p->>'action'='Remove' THEN 'Removed' WHEN oldname IS NULL THEN 'Added' ELSE 'Renamed' END,CASE WHEN p->>'action'='Remove' THEN 'Removed expense category '||oldname WHEN oldname IS NULL THEN 'Added expense category '||n ELSE 'Renamed expense category '||oldname||' to '||n END,cid::text); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.manage_petty_cash_category(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_petty_cash_category(jsonb) TO authenticated;
CREATE FUNCTION public.validate_petty_cash_category() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='Expense' THEN PERFORM pg_advisory_xact_lock(hashtextextended('petty-category-'||NEW.branch_id,0)); SELECT id,name INTO NEW.category_id,NEW.category FROM public.petty_cash_categories WHERE branch_id=NEW.branch_id AND name=NEW.category FOR KEY SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Choose an existing expense category'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_petty_category BEFORE INSERT ON public.petty_cash_entries FOR EACH ROW EXECUTE FUNCTION public.validate_petty_cash_category();